<?php

declare(strict_types=1);

namespace AIC\Component\Application;

use AIC\Component\Application\Templates\AtomTemplatesPart1;
use AIC\Component\Contracts\Component;
use AIC\Component\Exception\UnknownComponent;
use Override;

/**
 * Generated by composer run build from framework/templates/components (#92): the head of the template lookup (#98).
 * Do not edit; change the manifest and run composer run build.
 */
final readonly class AtomTemplates implements ComponentTemplates
{
    /**
     * @param ComponentTemplates $componentTemplates The chain's first templates.
     */
    public function __construct(
        private ComponentTemplates $componentTemplates = new AtomTemplatesPart1(),
    ) {
    }

    /**
     * @param Component  $component  A component.
     * @param RenderPass $renderPass The pass rendering it.
     *
     * @throws UnknownComponent When no template renders it.
     *
     * @return string Its markup, through the compiled library atom templates.
     */
    #[Override]
    public function compose(Component $component, RenderPass $renderPass): string
    {
        return $this->componentTemplates->compose($component, $renderPass);
    }
}
